def _env_int(name, default):
    """讀 int env（FIX-2c）：未設/空→default；壞值→印一行警告用 default（一個 typo 不該
       讓 uvicorn import 期崩潰起不來）。合法值行為與 int(os.environ.get(...)) 等價。"""
    v = os.environ.get(name)
    if v is not None and v != "":
        try:
            return int(v)
        except (TypeError, ValueError):
            print(f"[env] {name}={v!r} 非整數，改用預設 {default}", flush=True)
    return int(default)


def _env_float(name, default):
    """讀 float env（FIX-2c）：未設/空→default；壞值→印一行警告用 default。"""
    v = os.environ.get(name)
    if v is not None and v != "":
        try:
            return float(v)
        except (TypeError, ValueError):
            print(f"[env] {name}={v!r} 非數值，改用預設 {default}", flush=True)
    return float(default)


