def _ui_pick(qv, cv, allowed, default):
    """純函式：查詢參數優先、cookie 次之、都不合法 ⇒ 預設（認不得的值當沒給）。"""
    if qv in allowed:
        return qv
    if cv in allowed:
        return cv
    return default


def _ui_resolve(request):
    """→ `(ui, density)`；讀不到 request 的任何東西都退預設（永不 raise）。"""
    try:
        qp, ck = request.query_params, request.cookies
        return (_ui_pick(qp.get("ui"), ck.get(_UI_COOKIE), _UI_VALUES_PROC, UI_DEFAULT),
                _ui_pick(qp.get("density"), ck.get(_UI_DENSITY_COOKIE), UI_DENSITIES, "laptop"))
    except Exception:                                  # noqa: BLE001
        return UI_DEFAULT, "laptop"


def _ui_href(request, key, val):
    """當前網址換掉（或補上）一個查詢參數 ⇒ 其餘 query 原樣保留（§1.2「保留其餘 query」）。"""
    from urllib.parse import urlencode
    try:
        items = [(k, v) for k, v in request.query_params.multi_items() if k != key]
        path = request.url.path
    except Exception:                                  # noqa: BLE001
        items, path = [], "/"
    items.append((key, val))
    return path + "?" + urlencode(items)


def _ui_switch_href(request, ui, density=None):
    """版本切換連結（相對、不帶路徑）：只保留 lang／source，清掉 ui／density 後寫入這段的組合。
       不帶路徑與其他 query ⇒ 同一頁不論 tag／別名路由，nav 輸出逐位元相同（smoke byte-for-byte 釘）。"""
    from urllib.parse import urlencode
    try:
        items = [(k, v) for k, v in request.query_params.multi_items() if k in ("lang", "source")]
    except Exception:                                  # noqa: BLE001
        items = []
    items.append(("ui", ui))
    if density:
        items.append(("density", density))
    return "?" + urlencode(items)


def _ui_ctx(request):
    """UI v2 切換的**模板側**（context processor；同 `_tunnel_ctx` 一處接線）。"""
    ui, density = _ui_resolve(request)
    # `is_synth`（合成產線 WP-4b R-A5）：合成進程旗標一處注入所有模板（同 `_tunnel_ctx` 理由：
    #   新頁自動有、路由蓋不掉）。模板只在它為真時多印字 ⇒ 非合成進程輸出逐位元不變。
    return {"ui": ui, "density": density, "is_synth": _SYNTH_PROC,
            "ui_href": {"15": _ui_switch_href(request, "15", "laptop"),
                        "2": _ui_switch_href(request, "2", "projector")},
            "density_href": {d: _ui_href(request, "density", d) for d in UI_DENSITIES}}


def tpl(request, name):
    """`ui ∈ (15, 2)` 且 v2 版存在 ⇒ `v2/<name>`；其餘一律原名（未重做的頁自動回 v1）。"""
    ui, _d = _ui_resolve(request)
    if ui in ("15", "2") and (_UI_V2_DIR / name).is_file():
        return "v2/" + name
    return name


def _ui_cookie_headers(query_string):
    """純函式：從 raw query string 取合法的 `ui`／`density` ⇒ 要追加的 Set-Cookie 標頭。"""
    from urllib.parse import parse_qs
    try:
        qs = parse_qs(query_string.decode("latin-1"), keep_blank_values=False)
    except Exception:                                  # noqa: BLE001
        return []
    out = []
    for key, name, allowed in (("ui", _UI_COOKIE, UI_COOKIE_VALUES),
                               ("density", _UI_DENSITY_COOKIE, UI_DENSITIES)):
        v = (qs.get(key) or [None])[-1]
        if v in allowed:
            out.append((b"set-cookie",
                        (f"{name}={v}; Max-Age={_UI_COOKIE_MAX_AGE}; Path=/; SameSite=Lax")
                        .encode("latin-1")))
    return out


class _UiCookieMiddleware:
    """純 ASGI：請求帶合法 `?ui=`／`?density=` ⇒ 在 response start 追加 Set-Cookie。
       不讀不改 body（串流／CSV／JSON 端點逐位元不變）；沒帶參數 ⇒ 直接透傳。"""

    def __init__(self, asgi_app):
        self.app = asgi_app

    async def __call__(self, scope, receive, send):
        if scope.get("type") != "http":
            return await self.app(scope, receive, send)
        extra = _ui_cookie_headers(scope.get("query_string") or b"")
        if not extra:
            return await self.app(scope, receive, send)

        async def _send(msg):
            if msg.get("type") == "http.response.start":
                msg = dict(msg)
                msg["headers"] = list(msg.get("headers") or []) + extra
            await send(msg)
        return await self.app(scope, receive, _send)


app.add_middleware(_UiCookieMiddleware)


# ══════════════════════════════════════════════════════════════════════════════
# ★ 合成產線 Q-B／C-SY3 ④（WP-4a）：合成進程收到的任何 `?source=` 一律塌成 synth
#   （live／demo／snapshot／垃圾皆然）。在 ASGI 層改寫 query string ⇒ **所有**路由同一處生效，
#   包括沒有入口塌縮、把原值直接往資料層傳的路由（否則 `?source=demo` 會在 sandbox 上端出 demo 合成器）。
#   ⚠ 只在合成進程掛；非合成進程這段只是定義、`app` 物件的 middleware 堆疊逐位元不變。
# ══════════════════════════════════════════════════════════════════════════════
def _synth_query_string(qs):
    """純函式：raw query string（bytes）裡每個鍵為 `source` 的項目 → `source=synth`；其餘項目原樣保留
       （不重新編碼、不改順序）。沒有 `source` 鍵 ⇒ 原物件回傳。"""
    from urllib.parse import unquote_plus
    if not qs:
        return qs
    parts = qs.split(b"&")
    out, hit = [], False
    for part in parts:
        key = part.split(b"=", 1)[0]
        try:
            k = unquote_plus(key.decode("latin-1"))
        except Exception:                              # noqa: BLE001
            k = None
        if k == "source":
            out.append(b"source=" + _wrs.SOURCE_SYNTH.encode("ascii"))
            hit = True
        else:
            out.append(part)
    return b"&".join(out) if hit else qs


