#: 本進程實際監聽的埠（`_SynthSourceMiddleware` 由 ASGI scope["server"] 記下；只在 `_SYNTH_ASSIST` 時記）。
_SYNTH_SELF_PORT = {"port": None}


def _synth_url_parts(url):
    """→ (scheme, host, port, path, bad)；bad＝None 或拒絕理由（userinfo／query／fragment／空白／壞 URL）。"""
    from urllib.parse import urlsplit
    s = str(url or "").strip()
    if not s:
        return None, None, None, None, "unset"
    if any(c in s for c in "\\ \t\r\n"):
        return None, None, None, None, "backslash/whitespace in URL"
    try:
        u = urlsplit(s)
        host, port = u.hostname, u.port
    except ValueError as exc:
        return None, None, None, None, "unparseable URL (%s)" % (exc,)
    if u.username is not None or u.password is not None:
        return None, None, None, None, "userinfo not allowed"
    if u.query or u.fragment:
        return None, None, None, None, "query/fragment not allowed"
    return u.scheme.lower(), host, port, u.path, None


def _synth_gateway_url_ok(url):
    """純函式：錄影助理的 gateway base URL 可不可用 → `(ok, detail)`。
       只准 `http://<loopback>:<明寫埠>`、路徑空或 `/`、埠不在私機正式埠（8000／8787／18000）。"""
    scheme, host, port, path, bad = _synth_url_parts(url)
    if bad:
        return False, bad
    if scheme != "http":
        return False, "scheme %r not allowed (loopback http only)" % (scheme,)
    if not host or not _wrs.is_loopback_host(host):
        return False, "gateway host is not loopback"
    if port is None:
        return False, "gateway port must be explicit"
    if port in _SYNTH_ASSIST_FORBIDDEN_PORTS:
        return False, "gateway port %d is a private production port" % port
    if path not in ("", "/"):
        return False, "gateway base URL must not carry a path"
    return True, "loopback gateway :%d" % port


def _synth_mcp_target_ok(mcp_url, self_port, expected=None):
    """純函式：gateway 宣告的 MCP URL 是否就是本合成進程 → `(ok, detail)`。
       必須 `http://<loopback>:<埠>/mcp`，埠 ∈ {本進程埠, 本進程埠＋10000}，且兩者都不是私機正式埠。

       ★ PA2 `expected`（加性；值來自 env `BOARD_GW_MCP_URL_EXPECTED`，由 `_synth_assist_preflight` 傳入）：
         共用 gateway 跑在 Docker 裡，回打本進程要走 `http://host.docker.internal:<隧道埠>/mcp`＝**不是 loopback**。
         有設（去空白後非空）⇒ **可稽核的放行模式**：宣告值必須與 expected（去頭尾空白）**逐字相等**，
         才免掉 loopback 這一條；scheme http、無 userinfo／query／fragment、路徑 `/mcp`、明寫埠、
         埠 ∈ {本進程埠, ＋10000}、埠不在 8000／8787／18000——其餘條件**照舊全過**。
         沒設（None／空白）⇒ 原本 loopback 規則一字不改。"""
    exp = expected.strip() if isinstance(expected, str) else ""
    if not isinstance(self_port, int) or isinstance(self_port, bool) or self_port <= 0:
        return False, "own port unknown (no request seen yet)"
    if self_port in _SYNTH_ASSIST_FORBIDDEN_PORTS:
        return False, "this process listens on a private production port (%d)" % self_port
    scheme, host, port, path, bad = _synth_url_parts(mcp_url)
    if bad:
        return False, "gateway mcp_url " + bad
    if exp and mcp_url != exp:
        return False, "gateway mcp_url does not equal BOARD_GW_MCP_URL_EXPECTED"
    if scheme != "http":
        return False, "gateway mcp_url scheme %r not allowed" % (scheme,)
    if not exp and (not host or not _wrs.is_loopback_host(host)):
        return False, "gateway mcp_url host is not loopback"
    if port is None:
        return False, "gateway mcp_url port must be explicit"
    if port in _SYNTH_ASSIST_FORBIDDEN_PORTS:
        return False, "gateway mcp_url points at a private production port (%d)" % port
    if path != "/mcp":
        return False, "gateway mcp_url path must be /mcp"
    if port not in (self_port, self_port + _SYNTH_ASSIST_TUNNEL_OFFSET):
        return False, "gateway mcp_url port %d is not this process (%d or tunnel %d)" % (
            port, self_port, self_port + _SYNTH_ASSIST_TUNNEL_OFFSET)
    return True, "mcp target = this synthetic process (:%d)" % port


def _synth_path_allowed(path, assistant=None):
    """純函式：合成進程是否服務這個路徑（見 `_SYNTH_PATHS`）。
       `assistant`＝錄影助理開關（預設讀鎖定的 `_SYNTH_ASSIST`；只供測試注入）。關時與改動前逐位元同。"""
    p = str(path or "")
    if p in _SYNTH_PATHS or any(p.startswith(x) and len(p) > len(x) for x in _SYNTH_PREFIXES):
        return True
    if _SYNTH_ASSIST if assistant is None else assistant:
        return p in _SYNTH_ASSIST_PATHS or any(p.startswith(x) and len(p) > len(x)
                                               for x in _SYNTH_ASSIST_PREFIXES)
    return False


_SYNTH_REPLY_A_RE = None


def _synth_render_reply(text):
    """錄影助理（只在合成進程）：`wrender.render_reply` 原樣渲染後，把指向第一期外的站內連結收掉——
       裸 EID 的 `/updown`（R-A1 已移出第一期＝合成進程 404）改指 `/machine/<EID>`（第一期下鑽）；
       其餘第一期外的連結（`/daily`、`/yield`…）⇒ 只留已 escape 的標籤純文字（死連結比不連更糟）。
       輸入是 `render_reply` 自己產的 `<a href="…">…</a>`（href／標籤皆已 escape）⇒ 不新增任何未 escape 字串。"""
    global _SYNTH_REPLY_A_RE
    import html as _h
    import re as _re
    if _SYNTH_REPLY_A_RE is None:
        _SYNTH_REPLY_A_RE = (_re.compile(r'<a href="([^"]*)">(.*?)</a>', _re.S), _re.compile(r"EID-\d{5}"))
    a_re, eid_re = _SYNTH_REPLY_A_RE

    def _fix(m):
        path = _h.unescape(m.group(1)).split("#", 1)[0].split("?", 1)[0]
        if _synth_path_allowed(path):
            return m.group(0)
        if path == "/updown" and eid_re.fullmatch(m.group(2)):
            return '<a href="/machine/%s">%s</a>' % (m.group(2), m.group(2))
        return m.group(2)
    return a_re.sub(_fix, wrender.render_reply(text))


def _synth_basis_unlink(chips):
    """錄影助理：「依據」chip 的連結（信封 `page`）指向第一期外 ⇒ 合成進程會 404 ⇒ 不掛連結（`page=None`，
       chip 照印；同 `wassist._basis_page` 的「掛錯比留白糟」）。純函式；不改傳入物件。只在合成進程被呼叫。"""
    if not chips:
        return chips
    out = []
    for c in chips:
        p = c.get("page") if isinstance(c, dict) else None
        if p and not _synth_path_allowed(str(p).split("#", 1)[0].split("?", 1)[0]):
            c = dict(c, page=None)
        out.append(c)
    return out


if _SYNTH_ASSIST:   # 大聲印出（只印布林與 URL 核對結果，祕密／token 不印）
    _sa_ok, _sa_why = _synth_gateway_url_ok(os.environ.get("BOARD_HERMES_URL"))
    # PA2：多印公開旗標狀態（公開開的 ⇒ 標 PUBLIC；只有錄影旗標 ⇒ 照舊 FILMING-ONLY）與 MCP 預期值（可稽核：值照印，非祕密）
    print("[synth-assistant] %s assistant switch ON (%s=%s, %s=%s): gateway url %s (%s); secret set=%s; "
          "mcp token set=%s; mcp target expected=%s; /assistant/* opened, full page stays 404"
          % ("PUBLIC" if _PUBLIC_ASSIST else "FILMING-ONLY",
             ENV_SYNTH_ASSISTANT, int(_synth_assist_flag()), ENV_PUBLIC_ASSISTANT, int(_PUBLIC_ASSIST),
             "ok" if _sa_ok else "REFUSED", _sa_why,
             bool(os.environ.get("BOARD_HERMES_SECRET")), bool(os.environ.get("BOARD_MCP_TOKEN")),
             (os.environ.get(ENV_GW_MCP_URL_EXPECTED) or "").strip() or "unset (loopback rule)"), flush=True)
    # 對話庫落在改向後的狀態目錄（`core_paths.repo_root_path` ⇒ `<state>/_repo_root/`）；sqlite 不會自建目錄
    #   ⇒ 只在開關開時、且路徑確實在狀態目錄之下才建（不碰 repo、不碰明給的 `BOARD_ASSISTANT_DB`）。
    try:
        _sa_db_dir = os.path.dirname(os.path.abspath(wassist._db_path()))
        _sa_root = _wp.env_state_dir()
        if _sa_root and os.path.normcase(_sa_db_dir).startswith(os.path.normcase(os.path.abspath(_sa_root)) + os.sep):
            os.makedirs(_sa_db_dir, exist_ok=True)
    except Exception as _sa_e:                         # noqa: BLE001（建不起來＝第一輪著地 ai_fail，誠實）
        print("[synth-assistant] conversation store dir not prepared: %s" % type(_sa_e).__name__, flush=True)


class _SynthSourceMiddleware:
    """純 ASGI（只在合成進程掛）：①路徑不在第一期清單 ⇒ 404（不進任何路由）；
       ②改寫 scope 的 query_string（見 `_synth_query_string`）；不碰 body。"""

    def __init__(self, asgi_app):
        self.app = asgi_app

    async def __call__(self, scope, receive, send):
        if scope.get("type") == "http" and not _synth_path_allowed(scope.get("path")):
            body = b'{"detail":"Not Found"}'
            await send({"type": "http.response.start", "status": 404,
                        "headers": [(b"content-type", b"application/json"),
                                    (b"content-length", str(len(body)).encode("ascii"))]})
            await send({"type": "http.response.body", "body": body})
            return None
        if scope.get("type") == "http" and _SYNTH_ASSIST:      # 錄影助理：記下本進程的監聽埠（MCP 目標核對用）
            srv = scope.get("server")
            if isinstance(srv, (tuple, list)) and len(srv) > 1 and isinstance(srv[1], int):
                _SYNTH_SELF_PORT["port"] = srv[1]
        if scope.get("type") == "http":
            qs = scope.get("query_string") or b""
            new = _synth_query_string(qs)
            if new is not qs:
                scope = dict(scope)
                scope["query_string"] = new
        return await self.app(scope, receive, send)


if _SYNTH_PROC:
    app.add_middleware(_SynthSourceMiddleware)

templates = Jinja2Templates(directory=str(BASE / "templates"),
                            context_processors=[_tunnel_ctx, _ui_ctx])


def pretty_station(cls):
    """segCalibrationTest → 'Calibration Test'（純呈現層、非 §23 canonical key）。
       站別 class 不是 §23 十態，可自由轉顯示；title= 仍保留原始 cls。"""
    import re
    s = cls[3:] if isinstance(cls, str) and cls.startswith("seg") else cls
    return re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", s or "")


# ══════════════════════════════════════════════════════════════════════════════
# 標籤活動層的讀腿（M3 C6；SPEC-PRODUCT-TAGS §2.6-a）
# ══════════════════════════════════════════════════════════════════════════════
#   `board_data.read_family_activity()` 只讀落地日帳（**零 MES**），但一次要開 ≤N 份
#   JSON ⇒ 每個 chip 都重讀一次就是每頁幾百次 I/O。故在此以
#   **(日帳目錄最新 mtime, 檔數, N)** 為鍵快取一份：日帳一落地，鍵就換、下一個請求自然重讀。
#   ⚠ 讀不到／模組不在 ⇒ 回 `(None, {})`＝**legacy 模式**（chip 逐位元同 C6 之前），
#     不是「全部空心」——把「沒查」畫成「閒著」是這套設計最貴的錯（C-PT3）。
_TAG_ACT_LOCK = threading.Lock()
_TAG_ACT_CACHE = {"key": None, "val": (None, {})}


def _tag_activity_key(n_days):
    """快取鍵＝日帳目錄的 (最新 mtime, .json 檔數, 窗天數)。目錄不在 ⇒ 仍是穩定鍵。"""
    newest, cnt = 0.0, 0
    try:
        with os.scandir(wd.ledger_dir()) as it:
            for e in it:
                if e.name.endswith(".json") and e.is_file():
                    cnt += 1
                    m = e.stat().st_mtime
                    if m > newest:
                        newest = m
    except Exception:
        return (None, 0, n_days)
    return (round(newest, 3), cnt, n_days)


def _tag_activity():
    """→ `(activity, meta)` 給 `board_tagui.tag_chip`；失敗＝`(None, {})`＝誠實退 legacy。"""
    n_days = wtagui.recent_days()
    key = _tag_activity_key(n_days)
    with _TAG_ACT_LOCK:
        if _TAG_ACT_CACHE["key"] == key:
            return _TAG_ACT_CACHE["val"]
    try:
        val = wd.read_family_activity(days=n_days)
        if not (isinstance(val, tuple) and len(val) == 2):
            val = (None, {})
    except Exception as e:
        print(f"[tags] family activity unavailable ({type(e).__name__}: {str(e)[:120]}) "
              f"→ chips fall back to the capability-only form", flush=True)
        val = (None, {})
    with _TAG_ACT_LOCK:
        _TAG_ACT_CACHE["key"] = key
        _TAG_ACT_CACHE["val"] = val
    return val


#: WP-4b C 包 R-C1：合成下 chip tooltip 的鍵對照（既有鍵 → 不帶 `{families}` 的合成鍵；default 本來就不帶計數、照舊）。
_SYNTH_TAG_TIP = {"tag_tip_observed": "tag_tip_synth_observed", "tag_tip_recent": "tag_tip_synth_recent",
                  "tag_tip_idle": "tag_tip_synth_idle", "tag_tip_unknown": "tag_tip_synth_unknown"}


def _synth_tag_chip(model):
    """合成進程的 chip 模型（WP-4b R-C1）：拿掉 730 天普查段數（真實量測值），字母／origin／活動層照舊。

    ★ 只在 `_SYNTH_PROC` 為真時被呼叫（見下方 `tag_chip` 全域）⇒ 非合成進程連這支都不經過、逐位元不變。
    ★ 不改 `board_tagui` 與 `PRODUCT_TAGS`（普查常數屬公開發佈側、另案）：這裡只換呈現用的欄位——
      `tip_key` 換成不帶 `{families}` 的合成鍵（不是把 `{families}` 填空字串：那會留下「observed: 」殘句）、
      `facts`／`families`／`n`／`tip_args["families"]` 清空（模板不吃，但任何日後的消費端都拿不到計數）。"""
    if not isinstance(model, dict):
        return model
    chips = []
    for c in model.get("chips") or ():
        c2 = dict(c)
        c2["tip_key"] = _SYNTH_TAG_TIP.get(c.get("tip_key"), c.get("tip_key"))
        c2["facts"], c2["n"] = "", None
        c2["tip_args"] = dict(c.get("tip_args") or {}, families="")
        chips.append(c2)
    out = dict(model, chips=tuple(chips), families=(), facts="")
    out["tip_key"] = _SYNTH_TAG_TIP.get(model.get("tip_key"), model.get("tip_key"))
    return out


