DISP_UTIL_DAYS = 7                                      # util 取數窗＝基準窗（一份 data 兩用）
DISP_UTIL_WIN_H = _env_float("BOARD_DISP_UTIL_WIN_H", 4)
DISP_WO_DAYS = 1                                        # 否決閘① 的 cmms LIST 窗（只問「此刻」）
# WIP 側參數（SPEC §5.5；lookback 恆 ≥ age_cap，違者 clamp）
WIP_AGE_CAP_D = _env_int("BOARD_WIP_AGE_CAP_D", 14)
WIP_LOOKBACK_D = max(_env_int("BOARD_WIP_LOOKBACK_D", 21), WIP_AGE_CAP_D)
# 判準（D5：live 校準一律改 env 不改碼；名字 pin 在 SPEC §6.1）
DISP_COVER_THICK_H = _env_float("BOARD_DISP_COVER_THICK_H", 4)
DISP_COVER_THIN_H = _env_float("BOARD_DISP_COVER_THIN_H", 1)
DISP_UTIL_LOW_RATIO = _env_float("BOARD_DISP_UTIL_LOW_RATIO", 0.7)
DISP_RATE_LOW_RATIO = _env_float("BOARD_DISP_RATE_LOW_RATIO", 0.7)
DISP_BASE_FLOOR = _env_float("BOARD_DISP_BASE_FLOOR", 0.05)
_DISP_CACHE = {}      # (source, stop_min) → (t, board|None, wip)
# v2 綑板另有自己的 TTL/single-flight；材料仍只重用 `_DISP_CACHE` 內既有的 WIP／7d timeline。
KUN_DISP_TTL = _env_float("BOARD_KUN_DISP_TTL", DISP_TTL)
_KUN_DISP_CACHE = {}  # (source, stop_min, nominal_stamp, layout_stamp) → (t, board, v1, wip, meta)
_DISP_KUN_MATERIAL = {}  # (source, stop_min) → 本輪 v1 建板已讀到的零新 SQL 材料
# §5.6 亮燈去抖的跨輪狀態（SPEC-DISPATCH-V2 §5.6／§13 ⑰；2026-10-02）：
#   (source, stop_min) → {"cap", "streaks", "prev_streaks"}（`wkdisp.debounce_prev` 的形）。
#   ★ 「一張快照」＝一次 live WIP 重算（＝`_append_wip_snapshot` 寫一行的同一個節奏），以 `wip.cap` 認張；
#     同一份 WIP 再組一次板（`load_kun_dispatch` TTL 到期而 `_DISP_CACHE` 仍是同一份）**不算兩張**。
#   ★ 行程內記憶體、不落盤：重啟＝冷啟動＝第一輪每盞 lend／down 都只是「確認中」＝晚亮一輪（保守側），
#     不依賴 `BOARD_WIP_SNAPSHOT` 開關、不讀日帳、零 MES。
_KD_LIT_HIST = {}
_KD_LIT_LOCK = threading.Lock()

# ---- 人力欄（SPEC §9.3 D-OP1–D-OP4；計算核心＝`mes_operator`、取數＝`wd.get_operator*`）----
#   ★ **兩層窗、兩層 TTL**（規格明訂、勿合併）：counts 層＝分鐘級窄窗（便宜、短 TTL）；
#     分類層＝`class_d` 天掃描（貴一個量級、小時級 TTL）。合併成一個 TTL ＝ 每 5 分鐘打一次
#     7 天全線掃描。
#   ★ 判準 env 全可調（D-OP2 的 live 校準＝改 env 不改碼；名字 pin 在 SPEC §9.3）。
OPR_NOW_MIN = _env_int("BOARD_OPR_NOW_MIN", 60)              # 主值窗（分鐘）＝在場代理
OPR_REF_H = _env_int("BOARD_OPR_REF_H", 4)                   # 參考值窗（小時）＝班別規模
OPR_CLASS_D = _env_int("BOARD_OPR_CLASS_D", 7)               # 自動站分類窗（天）
OPR_AUTO_MAX_PERSONS = _env_int("BOARD_OPR_AUTO_MAX_PERSONS", 2)
OPR_AUTO_MIN_BLOCKS = _env_int("BOARD_OPR_AUTO_MIN_BLOCKS", 12)
OPR_TTL = _env_float("BOARD_OPR_TTL", 300)                   # counts 層快取（短）
OPR_CLASS_TTL = _env_float("BOARD_OPR_CLASS_TTL", 3600)      # 分類層快取（小時級）
OPR_TTL_FAIL = 60.0                                            # 失敗只黏 60s（既有降級紀律）
_OPR_CACHE = {}        # source → (t, canonical board.operator.v1)
_OPR_CLASS_CACHE = {}  # source → (t, class_layer)
# Landing 的綑級觀察人數是獨立的 warm-only 腿；不能借 dispatch 的名義編制，兩者口徑不同。
LD_OPR_WIN_MIN = _env_int("BOARD_LD_OPR_WIN_MIN", 60)
_OPR_KUN_CACHE = {}    # source → (monotonic_t, board.operator.v1 payload)

# util_note → i18n 鍵（誠實文案；`zero_len` ≠ `nosig` 兩套文案不得共用＝既有紀律）
_DISP_NOTE_KEY = {"zero_len": "dp_unmeasurable", "nosig": "dp_nosig", "nowin": "dp_nosig",
                  "thin_base": "dp_thin_base", "non_ast": "dp_non_ast",
                  "skipped": "dp_skipped_budget", "err": "dp_util_err",
                  "passthrough": "dp_passthrough"}
_DISP_GRP_KEY = {"assyModule": "dp_grp_ph", "assyUnit": "dp_grp_pc",
                 "assyPackagedUnit": "dp_grp_ppc"}


def _disp_th():
    """env → board_dispatch 判準（未設一律用 SPEC 草案值）。"""
    return wdisp.thresholds(cover_thick_h=DISP_COVER_THICK_H, cover_thin_h=DISP_COVER_THIN_H,
                            util_low_ratio=DISP_UTIL_LOW_RATIO,
                            rate_low_ratio=DISP_RATE_LOW_RATIO,
                            base_floor=DISP_BASE_FLOOR, util_win_h=DISP_UTIL_WIN_H,
                            base_days=DISP_UTIL_DAYS)


def _wip_params():
    return {"age_cap_d": WIP_AGE_CAP_D, "lookback_d": WIP_LOOKBACK_D,
            "rate_win_h": DISP_UTIL_WIN_H, "rate_fallback_d": DISP_UTIL_DAYS}


def _dispatch_util_ctx(source, wip, stop_min, budget_sec):
    """per-station 鑑別軸脈絡 → `{cls: {util_4h, base_7d, util_note, base_days_n, fleet_n, down_n}}`。

    ★ **零新 SQL 路徑**：util 與基準都從 `app.load(source, 7, stop_min, cls)` 的**同一份**
      canonical records 導出（既有 30s TTL＋single-flight）。
    ★ 否決閘①的工單只拉**一次** cmms LIST（`load_window_wos`，與 landing 各自 cache）；
      工單源未接通 → `down_n=None`（**不是 0**）＝閘關掉、footer 誠實註記。
    ★ 預算：逾時後剩餘站一律 `util_note='skipped'`＋util「—」，**不背景重打第二輪**。
    """
    t0 = time.perf_counter()
    ctx, skipped, probed = {}, 0, 0
    wos_by_eid, wo_status, _ws, we = load_window_wos(source, DISP_WO_DAYS)
    if wos_by_eid:
        # R2（SPEC-DORMANT §5.3）：母單補 scope_events（`_SCOPE_EV_CACHE` 共用；
        # 快取 dict ⇒ 先複本）⇒ down_eids 的機器視角才有範圍可看。失敗＝整機（高估側）。
        try:
            src_p, _sc_errs = _util_scope_src(wos_by_eid)
            if src_p:
                wos_by_eid = dict(wos_by_eid)
                wos_by_eid.update(src_p)
        except Exception as e:
            _logerr(f"dispatch scope {source}", e)
    dset = wdisp.down_eids(wos_by_eid, we)          # None ＝ 工單源未接通（絕不退成空集合）

    def blank(note):
        return {"util_4h": None, "base_7d": None, "util_note": note, "base_days_n": None,
                "fleet_n": 0, "down_n": None, "eids": (), "down_eids": None}

    for s in (wip.get("stations") or []):
        cls = s.get("cls")
        if s.get("passthrough"):
            ctx[cls] = blank("passthrough")
            continue
        if cls not in mt.EQP_STATIONS:              # 目檢/無設備站：util 結構性不可測（不是 0%）
            ctx[cls] = blank("non_ast")
            continue
        if (time.perf_counter() - t0) > budget_sec:
            skipped += 1
            ctx[cls] = blank("skipped")
            continue
        try:
            data = load(source, DISP_UTIL_DAYS, stop_min, cls=cls)
        except Exception as e:                      # 單站失敗只讓該站「—」，整板照出
            _logerr(f"dispatch util {cls} {source}", e)
            ctx[cls] = blank("err")
            continue
        u, un = wdisp.util_window(data, DISP_UTIL_WIN_H)
        b, bn, nd = wdisp.util_daily_median(data)
        eids = [m.get("eid") for m in (data.get("machines") or []) if m.get("eid")]
        cls_down = (frozenset(e for e in eids if e in dset) if dset is not None else None)
        ctx[cls] = {"util_4h": u, "base_7d": b, "util_note": un or bn, "base_days_n": nd,
                    "fleet_n": len(eids),
                    "down_n": (len(cls_down) if cls_down is not None else None),
                    # additive：v2 需每台的 truth，不可從站級計數反推；同一份 `app.load` 7d
                    # timeline 導出，零新 SQL。frozenset 防止消費端意外污染快取材料。
                    "eids": tuple(eids), "down_eids": cls_down}
        probed += 1
    return ctx, skipped, (dset is not None), wo_status, probed


def _opr_params():
    """env → `mes_operator` 參數（值即 SPEC §9.3 pin；env 只在 live 校準時動）。"""
    return {"now_min": OPR_NOW_MIN, "ref_h": OPR_REF_H, "class_d": OPR_CLASS_D,
            "max_persons": OPR_AUTO_MAX_PERSONS, "min_blocks": OPR_AUTO_MIN_BLOCKS}


def load_operator_class(source):
    """人力**分類層**（`class_d` 天掃描 → 自動站判定的唯一輸入）：小時級 TTL + single-flight。
       **恆不 raise**；失敗只黏 `OPR_TTL_FAIL`（VPN 一回來就重試，同既有失敗感知 TTL 紀律）。"""
    key = _source_key(source)
    if key != "live":                       # demo 的人力在 board_dispatch 合成、snapshot 不支撐
        return wd.get_operator_class(source, _opr_params())
    now = time.monotonic()

    def _fresh(h, t_now):
        return h and (t_now - h[0]) < (OPR_CLASS_TTL if (h[1] or {}).get("ok") else OPR_TTL_FAIL)
    hit = _OPR_CLASS_CACHE.get(key)
    if _fresh(hit, now):
        return hit[1]
    with _key_lock(("oprcls", key)):
        hit = _OPR_CLASS_CACHE.get(key)
        if _fresh(hit, time.monotonic()):
            return hit[1]
        t0 = time.perf_counter()
        try:
            cl = wd.get_operator_class(source, _opr_params())
        except Exception as e:              # get_operator_class 恆不 raise；保險起見仍包一層
            _logerr(f"operator class {source}", e)
            cl = {"ok": False, "unavailable": f"error:{type(e).__name__}", "rows": []}
        print(f"[operator/class {source}] {time.perf_counter() - t0:.1f}s "
              f"rows={len(cl.get('rows') or [])} unavailable={cl.get('unavailable')}", flush=True)
        _OPR_CLASS_CACHE[key] = (time.monotonic(), cl)
        return cl


def load_operator(source):
    """人力 canonical（`board.operator.v1`）：counts 層短 TTL + single-flight（分類層另有長 TTL）。

    ★ 實際刷新頻率由**板級快取**（`DISP_TTL`）主導——本層的短 TTL 是為了讓「板因別的鍵
      重建」時不必每次重打 counts 查詢，**不是**保證人力每 5 分鐘更新一次。
    ★ **恆不 raise**：任何失敗 → `wd.operator_unavailable(...)` ⇒ 人力欄整欄「—」＋
      footer `dp_mp_off`（絕不吞成一盤 0＝假裝現場沒人）。"""
    key = _source_key(source)
    now = time.monotonic()

    def _fresh(h, t_now):
        return h and (t_now - h[0]) < (OPR_TTL if wd.operator_ok(h[1]) else OPR_TTL_FAIL)
    hit = _OPR_CACHE.get(key)
    if _fresh(hit, now):
        return hit[1]
    with _key_lock(("opr", key)):
        hit = _OPR_CACHE.get(key)
        if _fresh(hit, time.monotonic()):
            return hit[1]
        t0 = time.perf_counter()
        try:
            opr = wd.get_operator(source, _opr_params(), class_layer=load_operator_class(source))
        except Exception as e:              # get_operator 恆不 raise；保險起見仍包一層
            _logerr(f"operator {source}", e)
            opr = wd.operator_unavailable(f"error:{type(e).__name__}", source)
        d = opr.get("diag") or {}
        print(f"[operator {source}] {time.perf_counter() - t0:.1f}s "
              f"stations={len(opr.get('stations') or {})} auto={d.get('n_auto')} "
              f"line_now={(opr.get('line') or {}).get('n_now')} "
              f"unavailable={opr.get('unavailable')}", flush=True)
        _OPR_CACHE[key] = (time.monotonic(), opr)
        return opr


def _ld_opr_kun_memberships(class_layer):
    """`CLS2KUN` → O3 parameter membership；D-OP2 先於 query 剔除。

    `class_layer.rows` 是已聚合的 `(cls, d7_persons, d7_blocks, d7_rows)`，不含任何
    識別值。缺分類資料不自行猜成 auto；整個 class layer 不可用則由 warmer 降級。
    passthrough 沒有綑的意義，故不進 O3 的 `VALUES` 表。
    """
    stats = {}
    for row in ((class_layer or {}).get("rows") or ()):
        try:
            stats[str(row[0])] = (int(row[1]), int(row[2]))
        except (IndexError, TypeError, ValueError):
            continue
    out = []
    for cls, mapping in wkdisp.CLS2KUN.items():
        try:
            _row, kun, kind = mapping
        except (TypeError, ValueError):
            continue
        if kind == "passthrough":
            continue
        p, b = stats.get(cls, (None, None))
        if p is not None and b is not None and p <= OPR_AUTO_MAX_PERSONS and b >= OPR_AUTO_MIN_BLOCKS:
            continue                              # D-OP2：自動帳號不當作作業員
        out.append((cls, kun))
    return out


def _ld_opr_kun_unavailable(source, why):
    return {"schema": "board.operator.v1", "ok": False, "source": source,
            "params": {"now_min": int(LD_OPR_WIN_MIN)}, "by_kun": {},
            "unavailable": str(why or "warming")}


LD_OPR_WARM_MIN_S = 120.0    # 兩次真查之間的最小間隔（見 `_ld_warm_opr_kun` 的節流理由）


def _ld_warm_opr_kun(source):
    """唯一可跑 O3 查詢的 landing warm path；頁面／`/landing/state` 只可呼叫 peek。

    人名紅線：這裡只從 `mes_operator` 取得已 `COUNT(DISTINCT OperatorId)` 的 `(kun,n)`，
    不接收也不保存任何 ID。成功資料另落 `opr.<source>.json`，C-LD23 三段老化由 peek 處理。

    ★ **節流（`LD_OPR_WARM_MIN_S`）**：這支是**唯一會打 MES 的 landing 端點**，而
      `BOARD_OPEN_ACCESS=1` 之下隧道對它沒有閘（它不在 `BLOCKED_PREFIXES` 裡）。
      暖機帶每 5 分鐘打一次；任何人多打的那幾次一律直接回既有快取，**不重打查詢**。
    """
    key = _source_key(source)
    hit = _OPR_KUN_CACHE.get(key)
    if (key == "live" and hit and isinstance(hit[1], dict) and hit[1].get("ok")
            and (time.monotonic() - float(hit[0])) < LD_OPR_WARM_MIN_S):
        return hit[1]
    if key == "demo":
        payload = {"schema": "board.operator.v1", "ok": True, "source": "demo",
                   "params": {"now_min": int(LD_OPR_WIN_MIN)},
                   "by_kun": wkdisp.demo_operator_by_kun()}
        _OPR_KUN_CACHE[key] = (time.monotonic(), payload)
        return payload
    if key != "live":
        payload = _ld_opr_kun_unavailable(key, "live_only")
        _OPR_KUN_CACHE[key] = (time.monotonic(), payload)
        return payload
    cl = load_operator_class(key)                 # warm endpoint 才可把長窗分類層叫暖
    if not (cl or {}).get("ok"):
        payload = _ld_opr_kun_unavailable(key, "class_layer:" + str((cl or {}).get("unavailable") or "missing"))
        _OPR_KUN_CACHE[key] = (time.monotonic(), payload)
        return payload
    members = _ld_opr_kun_memberships(cl)
    t0 = time.perf_counter()
    try:
        # 連線／編排形逐條照 `board_data.get_operator`（同一支 `mo._connect`、同一個
        # live 逾時），差別只有：這裡跑的是 [O3] 而不是 [O1]。
        # ★ `cap` 走 **`SELECT GETDATE()`**（MES 伺服器時鐘），不用 app 的牆鐘：
        #   `stpStartTime` 是伺服器時間，兩台機時鐘差幾分鐘就會讓「近 60 分鐘」那個窗
        #   系統性地偏掉，而畫面上完全看不出來（[[bash-date-clock-skew]] 的同一族坑）。
        import mes_operator as mo
        conn, cur = mo._connect()
        try:
            conn.timeout = wd.LIVE_QUERY_TIMEOUT_SEC
            mo.fetch_operator_guard(cur)
            cur.execute("SELECT GETDATE()")
            cap = cur.fetchone()[0]
            rows = mo.fetch_operator_kun_counts(cur, cap, members, now_min=LD_OPR_WIN_MIN)
        finally:
            try:
                conn.close()
            except Exception:
                pass
        payload = {"schema": mo.SCHEMA_ID, "ok": True, "source": key,
                   "cap": mo._dt(cap).isoformat(), "params": {"now_min": int(LD_OPR_WIN_MIN)},
                   "by_kun": mo.build_kun_counts(rows, members)}
        print(f"[landing/opr {key}] {time.perf_counter() - t0:.1f}s "
              f"kuns={len(payload['by_kun'])} members={len(members)}", flush=True)
        _OPR_KUN_CACHE[key] = (time.monotonic(), payload)
        _ld_lastgood_save("opr", key, payload)
        return payload
    except Exception as e:                                         # query failure is never a false 0
        _logerr("landing operator-by-kun warm", e)
        payload = _ld_opr_kun_unavailable(key, "error:" + type(e).__name__)
        _OPR_KUN_CACHE[key] = (time.monotonic(), payload)
        return payload


def _ld_peek_opr_kun(source):
    """O3 warm cache／last-good 的唯讀窺視，回 `(payload, age, tier, reason)`。"""
    key = _source_key(source)
    hit = _OPR_KUN_CACHE.get(key)
    if hit and isinstance(hit[1], dict) and hit[1].get("ok"):
        age = max(0.0, time.monotonic() - float(hit[0]))
        tier = _ld_age_tier(age)
        if tier != "warming":
            return hit[1], age, tier, ""
    lg = _ld_lastgood_load("opr", key)
    if lg is not None and isinstance(lg[0], dict) and lg[0].get("ok"):
        payload, age = lg
        tier = _ld_age_tier(age)
        if tier != "warming":
            return payload, age, tier, "lastgood"
    why = ((hit or (None, {}))[1] or {}).get("unavailable") or "warming"
    return None, None, "warming", str(why)


def _build_dispatch(source, stop_min):
    """→ (board|None, wip)。wip 不可用（含 snapshot 不支撐）→ board=None＝整板誠實降級。"""
    wip = wd.get_wip(source, params=_wip_params())
    if not wd.wip_ok(wip):
        _DISP_KUN_MATERIAL[(source, _clamp_stop_min(stop_min))] = {
            "util_ctx": {}, "wo_gate": False, "opr": None}
        return (None, wip)
    th = _disp_th()
    if source == "demo":
        return (wdisp.demo_dispatch(wip, th), wip)      # demo 人力＝wdisp.demo_operator（全合成）
    ctx, skipped, gate, wo_status, probed = _dispatch_util_ctx(
        source, wip, stop_min, DISP_BUDGET)
    opr = load_operator(source)                         # 人力欄（§9.3；失敗＝整欄「—」不擋板）
    board = wdisp.build_board(wip, ctx, th, wo_gate=gate, mode="live",
                              skipped_n=skipped, wo_status=wo_status, opr=opr)
    # 保留本輪已付出的材料給綑級板：`load_kun_dispatch` 不得再打一輪 7d timeline／工單。
    # 此 dict 不進 v1 canonical，亦不寫檔；它只活到相同 `(source, stop_min)` 快取重算為止。
    _DISP_KUN_MATERIAL[(source, _clamp_stop_min(stop_min))] = {
        "util_ctx": ctx, "wo_gate": gate, "opr": opr, "wo_status": wo_status}
    board["probed_n"] = probed
    # #24 stale-serve：閘開著但吃稍舊工單 ⇒ 頁上要講「截至幾點」。None ⇒ 模板整行不渲染。
    board["wo_asof_hm"] = (_wo_asof_hm(("wow", DISP_WO_DAYS))
                           if wo_status == "live_stale" else None)
    return (board, wip)


DISP_TTL_FAIL = 60.0          # 板不可用（VPN 斷/mes_wip 未就緒）：只黏 60s
DISP_TTL_PARTIAL = 120.0      # 板出來了但有站被預算砍掉：短 TTL，別把半空的板黏滿 10 分鐘


def _disp_ttl(board):
    """失敗/降級感知 TTL（比照 R1 輪的「失敗結果只黏 60s」修）。

    · `board is None`＝整板不可用 → 60s（源一恢復就重建）。
    · `skipped_n > 0`＝util 預算逾時、那些站是誠實「—」但**不是最終事實** → 120s。
      冷快取首建撞預算的話，舊版會把一塊幾乎全空的板整整黏 10 分鐘、期間不重試。
    · 其餘＝完整板 → `DISP_TTL`。
    """
    if board is None:
        return DISP_TTL_FAIL
    if (board or {}).get("skipped_n"):
        return min(DISP_TTL, DISP_TTL_PARTIAL)
    return DISP_TTL


def _kun_cache_key(source, stop_min):
    """檔案源換版立刻換綑板 cache key；v1 dispatch key/TTL 一個位元不動。"""
    return (source, _clamp_stop_min(stop_min), wd.kun_nominal_stamp(), wd.layout_doc_stamp())


def _kun_inputs_from_util(util_ctx):
    """7d timeline 的 additive EID 資訊 → D1 的兩個 per-machine 輸入（零新 SQL）。"""
    eid_classes, down_eids = {}, set()
    for cls, cell in (util_ctx or {}).items():
        if not isinstance(cell, dict):
            continue
        eids = tuple(cell.get("eids") or ())
        if eids:
            eid_classes[cls] = list(eids)     # D1 接受 cls → [eid, ...] 形
        if cell.get("down_eids") is not None:
            down_eids.update(cell.get("down_eids") or ())
    return eid_classes, down_eids


def _build_kun_from_dispatch(source, stop_min, wip):
    """消費本輪 v1 已取到的材料，組 D1 綑板；此處絕不自行打 MES/CMMS。"""
    source = _source_key(source)
    stop_min = _clamp_stop_min(stop_min)
    material = _DISP_KUN_MATERIAL.get((source, stop_min)) or {}
    util_ctx = material.get("util_ctx") or {}
    eid_classes, down_eids = _kun_inputs_from_util(util_ctx)

    # C-KD11：長停只窺 warm cache；窺不到就不把猜測交給核心，diag 如實說 off/warming。
    # ★ R41（Fable 2026-09-28 晚）：窺不到（未暖／被閘）時**退回橋常數**（`events=None` 是
    #   `board_dormant` 的既有慣例）——不再因 `events is None` 就讓長停座進分母。
    #   diag 的 `dormant_status` 照舊如實說 off/warming（來源揭露不變）。
    events, dormant_status, _age = _peek_a11_events()
    dormant_fn = lambda eid, day: wdorm.is_dormant(eid, day, events)

    nominal_doc, nominal_status = wd.load_kun_nominal_staff()
    nominal = {"doc": nominal_doc, "status": nominal_status,
               "stamp": wd.kun_nominal_stamp()}
    layout_doc, layout_status = wd.load_layout_doc()

    opr = material.get("opr")
    if not wd.operator_ok(opr):
        opr = None                             # C-KD2 校驗 chip 缺源＝None，不拿 0 補
    # §5.6 去抖：取上一張快照的連續亮燈數、組板、再把本張記成下一輪的「上一張」。
    #   鎖只包這一段（純函式組板＝毫秒級）；同一張 WIP 重組不前進（`debounce_prev` 的 advance=False）。
    cap = (wip or {}).get("cap")
    hist_key = (source, stop_min)
    with _KD_LIT_LOCK:
        lit_prev, advance = wkdisp.debounce_prev(_KD_LIT_HIST.get(hist_key), cap)
        board = wkdisp.build_kun_board(
            wip or {}, util_ctx, down_eids, dormant_fn, nominal, layout_doc,
            opr=opr, now=cap, mode=source,
            wo_gate=bool(material.get("wo_gate")), eid_classes=eid_classes,
            lit_prev=lit_prev)
        if advance:
            _KD_LIT_HIST[hist_key] = {"cap": cap, "streaks": wkdisp.lit_streaks(board),
                                      "prev_streaks": lit_prev}
    # schema additive diag：來源有無被窺到是誠實資訊，不影響 D1 純函式的燈／配對。
    board.setdefault("diag", {}).update({"layout_status": layout_status,
                                           "dormant_status": dormant_status or "warming"})
    return board, {"nominal": nominal_doc, "nominal_status": nominal_status,
                   "layout_status": layout_status, "dormant_status": dormant_status}


def _wip_snapshot_payload(wip, kun_board=None):
    """§9 日帳白名單：沒有 lot、沒有姓名、沒有未列出的頂層鍵。"""
    stations = []
    for row in (wip or {}).get("stations") or ():
        if not isinstance(row, dict):
            continue
        stations.append({key: row.get(key) for key in
                         ("cls", "queue_n", "stale_n", "rate_uph", "rate_src", "cover_h")})
    line = (wip or {}).get("line") or {}
    payload = {
        "cap": (wip or {}).get("cap"),
        "stations": stations,
        "line": {key: line.get(key) for key in
                 ("live_total", "queue_total", "stale_total", "fail_hold_total")},
    }
    if kun_board:
        # ★ 2026-10-02 additive（§5.6）：`lamp`＝頁面燈（去抖後）；`lamp_raw`＝去抖前判定、
        #   `lit_streak`＝連續亮燈張數——回測要重放去抖必須看得到 raw（舊行缺這兩鍵＝raw 即 lamp）。
        payload["kuns"] = [{key: row.get(key) for key in
                            ("kun", "lamp", "lend", "need", "idle_frac", "dry_at",
                             "lamp_raw", "lit_streak")}
                           for row in (kun_board.get("kuns") or [])]
    return payload


def _append_wip_snapshot(wip, kun_board=None):
    """live WIP 重算成功後 append 一行；落盤失敗只記 log，絕不影響頁面。"""
    if os.environ.get("BOARD_WIP_SNAPSHOT", "1") == "0" or not wd.wip_ok(wip):
        return
    try:
        from datetime import datetime as _dt
        from _probe_kun_activity import production_day as _production_day
        cap = (wip or {}).get("cap")
        now = cap if isinstance(cap, _dt) else _dt.fromisoformat(str(cap).replace("Z", "+00:00"))
        day = _production_day(now).isoformat()
        snap_dir = os.path.join(os.path.dirname(wd.ledger_dir()), "wip_snapshots")
        os.makedirs(snap_dir, exist_ok=True)
        path = os.path.join(snap_dir, f"{day}.jsonl")
        import json as _json
        with open(path, "a", encoding="utf-8") as fh:
            fh.write(_json.dumps(_wip_snapshot_payload(wip, kun_board), ensure_ascii=False,
                                 separators=(",", ":")) + "\n")
    except Exception as e:                    # 日帳是旁路；不能拖倒本頁。
        _logerr("dispatch wip snapshot", e)


def load_dispatch(source, stop_min):
    """調度板 TTL 快取 + single-flight（比照 load_eqm/load_maint）。**恆不 raise**：
       任何失敗 → (None, wip_unavailable(...))＝body 顯降級說明、絕不假造燈號。

       ★ `source` **在分派點正規化**（2026-08-03 E-③；同 `load_attrib`/`load_unit` 教訓）：
         `_build_dispatch` 只有 `source == "demo"` 走合成分支，任意 `?source=垃圾` 會落進
         **live 分支**＝一個亂打的網址就對 MES 開連線（且鍵早就塌成 demo ⇒ 拿到的板還會
         與鍵不同源）。只入鍵是不夠的。"""
    source = _source_key(source)
    key = (source, _clamp_stop_min(stop_min))
    now = time.monotonic()
    hit = _DISP_CACHE.get(key)

    def _fresh(h, t_now):
        return h and (t_now - h[0]) < _disp_ttl(h[1])
    if _fresh(hit, now):
        return hit[1], hit[2]
    with _key_lock(("disp",) + key):
        hit = _DISP_CACHE.get(key)
        if _fresh(hit, time.monotonic()):
            return hit[1], hit[2]
        t0 = time.perf_counter()
        try:
            board, wip = _build_dispatch(source, _clamp_stop_min(stop_min))
        except Exception as e:
            _logerr(f"dispatch {source}", e)
            board, wip = None, wd.wip_unavailable(f"error:{type(e).__name__}", source)
        el = time.perf_counter() - t0
        print(f"[dispatch/body {source}] {el:.1f}s "
              f"rows={board['n_rows'] if board else 'NA'} "
              f"need={board['n_need'] if board else '-'} "
              f"lend={board['n_lend'] if board else '-'} "
              f"down={board['n_down'] if board else '-'} "
              f"probed={board.get('probed_n') if board else '-'} "
              f"skipped={board['skipped_n'] if board else '-'} "
              f"wo_gate={board['wo_gate'] if board else '-'} "
              f"opr={((board or {}).get('opr') or {}).get('ok') if board else '-'} "
              f"opr_auto={((board or {}).get('opr') or {}).get('n_auto') if board else '-'} "
              f"wip={'ok' if wd.wip_ok(wip) else (wip or {}).get('unavailable')}", flush=True)
        _DISP_CACHE[key] = (time.monotonic(), board, wip)
        # §9：只在 live 的**本次成功重算**後 append。綑結果吃剛剛那份 7d timeline material；
        # 若其組裝腿意外失敗，WIP 日帳照寫、綑欄位誠實省略，頁面也不受影響。
        if source == "live" and board is not None and wd.wip_ok(wip):
            kun_board = None
            try:
                kun_board, kun_meta = _build_kun_from_dispatch(source, key[1], wip)
                _KUN_DISP_CACHE[_kun_cache_key(source, key[1])] = (
                    time.monotonic(), kun_board, board, wip, kun_meta)
            except Exception as e:
                _logerr("kun dispatch prebuild", e)
            _append_wip_snapshot(wip, kun_board)
        return board, wip


def load_kun_dispatch(source, stop_min):
    """綑級調度板 TTL + single-flight。

    WIP/v1 板恆經 `load_dispatch` 取得；live 綑判定只吃它本輪已載入的 7d timeline／WO
    material。demo 則只吃 D1 的確定性 `demo_kun_dispatch()`，不混本機檔案或 live 訊號。
    """
    source = _source_key(source)
    stop_min = _clamp_stop_min(stop_min)
    key = _kun_cache_key(source, stop_min)

    def _fresh(hit, now):
        return hit and (now - hit[0]) < KUN_DISP_TTL

    hit = _KUN_DISP_CACHE.get(key)
    if _fresh(hit, time.monotonic()):
        return hit[1], hit[2], hit[3], hit[4]
    with _key_lock(("kun_disp",) + key[:2]):
        # 名義配置或 layout 在等待鎖期間換檔時，重新取 key，避免把舊檔結果塞回新印記。
        key = _kun_cache_key(source, stop_min)
        hit = _KUN_DISP_CACHE.get(key)
        if _fresh(hit, time.monotonic()):
            return hit[1], hit[2], hit[3], hit[4]
        t0 = time.perf_counter()
        v1, wip = load_dispatch(source, stop_min)
        try:
            # demo 的綑訊號完整由 D1 fixture 給定；不能被本機 WIP 檔缺席摻成半真半假。
            if source == "demo":
                board, meta = wkdisp.demo_kun_dispatch(), {
                    "nominal": None, "nominal_status": "demo", "layout_status": "demo",
                    "dormant_status": "demo"}
            else:
                board, meta = _build_kun_from_dispatch(source, stop_min, wip)
        except Exception as e:
            _logerr(f"kun dispatch {source}", e)
            board, meta = None, {"error": _errstr(e)}
        print(f"[kun_dispatch/body {source}] total={time.perf_counter()-t0:.1f}s "
              f"kuns={len((board or {}).get('kuns') or [])} "
              f"pairs={len((board or {}).get('pairs') or [])} "
              f"wip={'ok' if wd.wip_ok(wip) else (wip or {}).get('unavailable')}", flush=True)
        _KUN_DISP_CACHE[key] = (time.monotonic(), board, v1, wip, meta)
        return board, v1, wip, meta


def _peek_disp(source, stop_min=15):
    """綑級調度板的 **warm-only 窺視**（landing 窗 4 用；`SPEC-DISPATCH-V2.md` §8）。

       ★ 形狀逐條照抄 `_peek_eqm`（同一條紀律的第三個實例），三件都不可省：
         ① **只窺快取、絕不觸發重建**——`load_kun_dispatch` 的 live 腿要掃 WO LIST ＋ 7d
            timeline（動輒數十秒），站台根不該為了一張小表付那個錢（C-LD18／FP-8）。
            窺不到就是窺不到，**不退回去同步取一次**（那正是 FP-8 的雙重逾時）。
         ② **鍵組成逐位元同 `load_kun_dispatch`**＝`_kun_cache_key(source, stop_min)`
            （含 `_source_key` 正規化、`_clamp_stop_min`、名義配置與 layout 的 `(mtime,size)`
            印記）。漂一位就是**永遠窺不到**，而且沒有任何測試會紅——這正是 `_peek_eqm`
            當年吃過的虧（#39）。**改 `_kun_cache_key` 的人必須同時看這裡。**
         ③ **stale-tolerant**（`_PEEK_DISP_STALE_MAX_S`）：TTL 過期但仍在上限內照樣回，
            age 交給呼叫端去講「幾分鐘前的快照」。
       ⚠ `stop_min` 預設 15 ＝ `/dispatch` 路由的預設值。兩者不同 ⇒ 窺的是另一把鍵、
         永遠 miss（頁面天天顯「暖機中」而沒有人看得出為什麼）。
       ★ demo：直接取 D1 的確定性合成板（純函式、零 I/O、零快取），**不走 `load_kun_dispatch`**
         ——那一支會連帶建 v1 demo 板，而窗 4 的四個欄位一個都不需要它。
       回 `(kun_board, v1_board, wip, meta, age_s)` 或 `None`（＝暖機中）。"""
    source = _source_key(source)
    if source == "demo":
        return (wkdisp.demo_kun_dispatch(), None, None,
                {"nominal": None, "nominal_status": "demo", "layout_status": "demo",
                 "dormant_status": "demo"}, 0.0)
    hit = _KUN_DISP_CACHE.get(_kun_cache_key(source, stop_min))
    if not hit:
        return None
    age = time.monotonic() - hit[0]
    if age > max(KUN_DISP_TTL, _PEEK_DISP_STALE_MAX_S):
        return None
    return (hit[1], hit[2], hit[3], hit[4], age)


def _disp_ctx(source, lang, board=None, wip=None):
    t = I18N[resolve_lang(lang)]

    def reason(r):
        """原因短語（**必帶數字**；proxy 路徑再附 (rate proxy) 標記）。未知鍵→空字串不炸。"""
        key = (r or {}).get("reason_key")
        try:
            s = t[key].format(**((r or {}).get("reason_args") or {}))
        except (KeyError, IndexError, ValueError):
            return ""
        if (r or {}).get("util_src") == "proxy":
            s += " " + t["dp_proxy_note"]
        return s

    def mp_tip(cell):
        """人力欄 ?-hover（四態各自的誠實文案 ＋ 該站分類依據＝使用者可自驗 D-OP2）。
           **永不在此洩任何識別值**——cell 只有五個整數（`board_dispatch.operator_cell` 白名單）。"""
        c = cell or {}
        st = c.get("state")
        p = ((board or {}).get("opr") or {}).get("params") or {}
        if st == "count":
            s = t["dp_mp_tip"].format(n=p.get("now_min") or OPR_NOW_MIN, m=c.get("n_4h"))
        elif st == "auto":
            s = t["dp_mp_auto"]
        elif st == "nosig":
            s = t["dp_mp_nosig"].format(d=p.get("class_d") or OPR_CLASS_D)
        else:
            return t["dp_mp_off"]
        if c.get("d7_persons") is not None and c.get("d7_blocks") is not None:
            s += " " + t["dp_mp_diag"].format(
                d=p.get("class_d") or OPR_CLASS_D, p=c.get("d7_persons"),
                b=c.get("d7_blocks"), mp=p.get("auto_max_persons") or OPR_AUTO_MAX_PERSONS,
                mb=p.get("auto_min_blocks") or OPR_AUTO_MIN_BLOCKS)
        return s

    return {"source": source, "board": board, "wip": wip,
            "dp_reason": reason,
            "dp_note": (lambda n: t.get(_DISP_NOTE_KEY.get(n, ""), "") if n else ""),
            "dp_grp": (lambda m: t.get(_DISP_GRP_KEY.get(m, "dp_grp_other"), "")),
            "dp_mp_tip_of": mp_tip,
            "util_win_h": DISP_UTIL_WIN_H, "base_days": DISP_UTIL_DAYS,
            "opr_now_min": OPR_NOW_MIN, "opr_ref_h": OPR_REF_H, "opr_class_d": OPR_CLASS_D}


def _kd_need_proxy_args(v1):
    """`kd_r_need` 的速率代理形材料（ROADMAP #82④／原 #75 備註；**純函式、純文案**）。

       v1 調度列的 `util_src == "proxy"`＝這一站稼動結構性不可測、燈是**速率代理**判的
       （`board_dispatch.util_axis`：`rate_4h < rate_7d × ratio`）。那一格本來就沒有稼動可印，
       舊句印「稼動 —」＝把拿得到的那把尺藏起來 ⇒ 改印「速率代理 ~0.2/h vs 基準 ~3.1/h」。
       ★ 數字**只有一個出處**：v1 列 `classify` 已經格式化好的 `reason_args.cur／base`
         （`/dispatch` 站列那一句用的就是它們）；舊列缺 `reason_args` 才退回同一個 `~%.1f/h` 形
         讀 `rate_uph_4h／7d`。兩個都拿不到 ⇒ 回 None（呼叫端維持原句、不印半句）。"""
    row = v1 if isinstance(v1, dict) else {}
    if row.get("util_src") != "proxy":
        return None
    ra = row.get("reason_args") or {}

    def _rate(v):
        try:
            return None if v is None else "~%.1f/h" % float(v)
        except (TypeError, ValueError):
            return None

    cur = ra.get("cur") if ra.get("cur") not in (None, "", "—") else _rate(row.get("rate_uph_4h"))
    base = (ra.get("base") if ra.get("base") not in (None, "", "—")
            else _rate(row.get("rate_uph_7d")))
    if not cur or not base:
        return None
    return {"cur": cur, "base": base}


def _kd_ctx(source, lang, kun_board=None, v1_board=None, wip=None, meta=None):
    """綑板的顯示投影：顯示層只拿 PLOVER 站名，永不把內部綑代號帶進 HTML。"""
    import board_manpower as wman

    t = I18N[resolve_lang(lang)]
    lang = resolve_lang(lang)
    board = kun_board or {}
    by_kun = {row.get("kun"): row for row in (board.get("kuns") or []) if isinstance(row, dict)}
    v1_rows = list((v1_board or {}).get("rows") or [])
    # 展開列是綑板自己的 v1 白名單複本。尤其 demo 的綑板與舊 v1 demo 是兩套
    # 獨立情境，絕不可把後者塞進前者的 details，否則同一綑會有兩把燈尺。
    #   排序回 v1 的 ord 序：D1 的 `stations` 是按「機器類 → 人工類」堆的，直接照印會讓下鑽
    #   的列號跳號（2,1,3,5），而 v1 的 mcl 分組列首靠「前一列 mcl 不同」判斷 ⇒ 沒排序時
    #   同一個分組會被切成好幾段列首。排序只動顯示順序，不動任何一列的值。
    v1_by_kun = {kun: sorted(((item or {}).get("stations") or ()),
                             key=lambda row: (row or {}).get("ord") or 0)
                 for kun, item in by_kun.items()}
    station_by_cls = {row.get("cls"): row
                      for rows in v1_by_kun.values() for row in rows if row.get("cls")}
    orphans = []
    for row in v1_rows:
        mapping = wkdisp.CLS2KUN.get(row.get("cls"))
        if not (mapping and mapping[1] in by_kun and mapping[1] not in ("passthrough",)
                and mapping[2] not in ("blind",)):
            orphans.append(row)

    plover_by_kun = {}
    for _area, rows in wman.PLOVER_BLOCKS:
        for no, en, zh, kun, _eids in rows:
            if kun in wkdisp.BLIND_KUNS:
                continue
            row_classes = [cls for cls, mapping in wkdisp.CLS2KUN.items()
                           if mapping[1] == kun
                           and str(no) in str(mapping[0]).replace("/", "／").split("／")]
            plover_by_kun.setdefault(kun, []).append({
                "no": no, "name": (pretty_station(row_classes[0]) if row_classes else
                                      (en or zh or "—")),
                "en": en, "zh": zh})

    def _member_names_en(kun):
        """§18.9：綑的成員站名永遠採 `pretty_station` 英文，與 UI 語言無關。"""
        return list(dict.fromkeys(
            pretty_station(cls) for cls, mapping in wkdisp.CLS2KUN.items()
            if mapping[1] == kun and mapping[2] != "passthrough"))

    def _first_name(kun):
        names = _member_names_en(kun)
        if names:
            return names[0]
        return (by_kun.get(kun) or {}).get("first_station") or "—"

    def _bundle_names(kun):
        """綑不是命名實體：首列顯示成員站名，完整列留給 title 消費者。"""
        names = _member_names_en(kun)
        full = " · ".join(names) or _first_name(kun)
        if len(names) <= 3:
            return full, full
        return " · ".join(names[:2] + [t["kd_bundle_more"].format(n=len(names) - 2)]), full

    def _fmt_hm(value):
        if not value:
            return "—"
        try:
            from datetime import datetime as _dt
            return _dt.fromisoformat(str(value).replace("Z", "+00:00")).strftime("%H:%M")
        except Exception:
            return "—"

    def _fmt_dt(value):
        """ISO 時間戳 → `YYYY-MM-DD HH:MM`（頁首 as-of 用）。

        綑板的 `as_of` 是 `datetime.isoformat()` 原樣（live 曾印出
        `2026-09-05T13:21:03.920000`，微秒對看板毫無意義）。解析失敗一律**退回原字串**，
        不吞掉資訊、也不假造時間。
        """
        if not value:
            return value
        try:
            from datetime import datetime as _dt
            return _dt.fromisoformat(str(value).replace("Z", "+00:00")).strftime("%Y-%m-%d %H:%M")
        except Exception:
            return value

    def _fmt_num(value):
        return "—" if value is None else ("%.1f" % float(value)).rstrip("0").rstrip(".")

    def _lamp(item):
        lamp = item.get("lamp")
        lend = item.get("lend") or {}
        need = item.get("need") or {}
        # §5.6 去抖壓住的燈：機讀燈＝ok（不配對、不進 landing 行動清單），燈字印「確認中」
        #   ——不印「正常」，因為原判定其實是 lend／down、只是還沒連續兩張。
        if item.get("lit_held") and item.get("lamp_reason") == wkdisp.LIT_HELD_REASON:
            return t["kd_lamp_confirming"]
        if lamp == "lend":
            return (t["kd_lamp_lend"].format(n=lend.get("now")) if lend.get("now") else
                    t["kd_lamp_half"])
        if lamp == "need":
            return t["kd_lamp_need"].format(n=need.get("n"))
        return t.get("kd_lamp_" + str(lamp), t["kd_lamp_na"])

    def _reason(item):
        key = item.get("lamp_reason") or "kd_r_nodiag"
        machines, need, lend = item.get("machines") or {}, item.get("need") or {}, item.get("lend") or {}
        need_cls = (need.get("stations") or [None])[0]
        v1 = station_by_cls.get(need_cls, {})
        # ROADMAP #82④：速率代理站換句（純文案；燈與判定一個位元不動）。
        _proxy = _kd_need_proxy_args(v1) if key == "kd_r_need" else None
        if _proxy:
            key = "kd_r_need_proxy"
        args = {
            "station": v1.get("display") or _first_name(item.get("kun")),
            "cover": ("%.1f h" % v1["cover_h"]) if v1.get("cover_h") is not None else "—",
            "util": ("%.0f%%" % (100 * v1["util_4h"])) if v1.get("util_4h") is not None else "—",
            "down": machines.get("down_n") if machines.get("down_n") is not None else "—",
            "dry": machines.get("dry_n") if machines.get("dry_n") is not None else "—",
            "idle": _fmt_num((item.get("idle_frac") or 0) * (machines.get("roster_n") or 0)),
            "denom": (machines.get("roster_n") or 0) - (machines.get("dormant_n") or 0),
            "at": _fmt_hm(item.get("dry_at")),
        }
        if _proxy:
            args.update(_proxy)
        try:
            return t[key].format(**args)
        except (KeyError, IndexError, ValueError):
            return t["kd_r_nodiag"]

    def _dry(item):
        if not item.get("dry_at"):
            return "—"
        horizon = ((board.get("diag") or {}).get("horizons") or {}).get(item.get("region")) or {}
        end = horizon.get("end")
        if end and str(item["dry_at"]) > str(end):
            return t["kd_dry_after"]
        # §13 ⑯(c)：預測＝此刻、但機器站近 4h 仍有吞吐 ⇒ 不印一個等於現在的時刻。
        if wkdisp.dry_now_running(item, board.get("as_of")):
            return t["kd_dry_now_running"]
        # §13 ⑯(b)：feed_h 是**下界**（回測：實際料盡普遍更晚）⇒「最早約 HH:MM」。
        return t["kd_dry_time"].format(at=_fmt_hm(item.get("dry_at")))

    def _measured_tip(item):
        parts = []
        for cls, value in (item.get("measured_by_station") or {}).items():
            row = station_by_cls.get(cls, {})
            label = row.get("display") or cls
            parts.append(f"{label}: {'—' if value is None else '≥' + str(value)}")
        return " · ".join(parts) or t["kd_foot_measured"]

    blocks = []
    for index, (kun, item) in enumerate((k, by_kun[k]) for k in by_kun if k in plover_by_kun):
        machine = item.get("machines") or {}
        denom = (machine.get("roster_n") or 0) - (machine.get("dormant_n") or 0)
        staff = item.get("staff_n")
        # §13 ⑭：N＝0（有登記、本班 0 人）≠ 未登記——印「本班未配人」，可借不主張。
        staff_note = (t["kd_staff_stale"].format(as_of=((meta or {}).get("nominal") or {}).get("as_of") or "—")
                      if str(item.get("staff_src")) == "stale" else
                      t["kd_no_staff"] if staff is None else
                      t["kd_staff_zero"] if staff == 0 else "")
        bundle_name, bundle_title = _bundle_names(kun)
        blocks.append({
            "band": index % 4, "first_station": bundle_name, "rows": plover_by_kun[kun],
            "kun": kun, "bundle_name": bundle_name, "bundle_title": bundle_title,
            "v1_rows": v1_by_kun.get(kun, []), "item": item,
            "work": f"{machine.get('work_n', '—')}/{denom if denom > 0 else '—'}",
            "dry": _dry(item), "staff": staff, "staff_note": staff_note,
            "lamp_text": _lamp(item), "reason": _reason(item),
            "measured": item.get("measured_ge"), "measured_tip": _measured_tip(item),
        })

    # ★ §17.2：配對帶與綑首列**同一個名字**＝成員站名列（`_bundle_names(kun)[0]`）。
    #   舊寫法是首站名＋「那綑」／「bundle」字尾——那正是 Chris 批的「替綑取名」，
    #   而且會讓同一綑在首列與配對帶上長成兩個樣子。
    #   （`_bundle_names` 對沒有 PLOVER 站列的綑會自己退回 `_first_name`，不會空手。）
    visible = {kun: _bundle_names(kun)[0] for kun in by_kun}

    def _pair_text(pair):
        left, right = by_kun.get(pair.get("from"), {}), by_kun.get(pair.get("to"), {})
        lend = t["kd_lamp_half"] if pair.get("half") else t["kd_lamp_lend"].format(n=pair.get("n"))
        need = (t["kd_lamp_half_need"] if pair.get("half") else
                t["kd_lamp_need"].format(n=pair.get("n")))
        dist = (t["kd_p_nodist"] if pair.get("dist_m") is None else
                "%.1f m" % float(pair.get("dist_m")))
        return t["kd_pair_line"].format(from_=visible.get(pair.get("from"), "—"), lend=lend,
                                        to=visible.get(pair.get("to"), "—"), need=need,
                                        dist=dist, reason=t.get(pair.get("reason"), ""))

    horizons = []
    for region, horizon in ((board.get("diag") or {}).get("horizons") or {}).items():
        if horizon.get("kind") == "shift_end":
            value = t["kd_horizon_shift"].format(shift=t.get("kd_shift_" + str(horizon.get("shift")),
                                                               horizon.get("shift") or "—"),
                                                  end=_fmt_hm(horizon.get("end")))
        else:
            value = t["kd_horizon_fallback"].format(h=_fmt_num(horizon.get("hours_left")))
        horizons.append(t["kd_region"].format(region=region, horizon=value))
    diag = board.get("diag") or {}
    # 顯示層淺複本：只把頁首要印的 `as_of` 格式化成 `YYYY-MM-DD HH:MM`，其餘鍵原樣帶過。
    # **不就地改綑板**——綑板是快取物件，就地改會污染其他消費者的機讀值。
    kd_board_disp = kun_board
    if isinstance(kun_board, dict) and kun_board.get("as_of"):
        kd_board_disp = dict(kun_board)
        kd_board_disp["as_of"] = _fmt_dt(kun_board.get("as_of"))
    return {"kd_board": kd_board_disp, "kd_blocks": blocks, "kd_orphans": orphans,
            "kd_wip_ready": wd.wip_ok(wip), "kd_pairs": [_pair_text(p) for p in board.get("pairs") or []],
            "kd_fallback_pairs": [_pair_text(p) for p in board.get("fallback_pairs") or []],
            "kd_horizons": horizons, "kd_nominal": (meta or {}).get("nominal"),
            "kd_layout_status": diag.get("layout_status"), "kd_dormant_status": diag.get("dormant_status"),
            "kd_wo_gate": diag.get("wo_gate"), "kd_offshift": any(
                h.get("kind") == "fallback" for h in (diag.get("horizons") or {}).values()),
            "kd_lamp_of": _lamp, "kd_reason_of": _reason, "kd_measured_tip": _measured_tip,
            "kd_pair_text": _pair_text}


# ---------------------------------------------------------------------------
# /manpower —— 綑級人力頁（ROADMAP #40；SPEC-MANPOWER.md C-MP1–13、§4① 拍板＝生產組主列）
#   資料源＝檔案快照（C-MP3：頁面絕不連 MES）；快取鍵吃 raw `(mtime,size)` 印記
#   ⇒ Chris 換 raw 當天生效、不必重啟。source 參數對本頁沒有資料語意（只給 nav 連結）。
# ---------------------------------------------------------------------------
_MP_CACHE = {}


def _load_manpower_board(days_req=None):
    import board_manpower as wm
    if days_req not in wm.DAYS_CHOICES:
        days_req = wm.DAYS_DEFAULT
    stamp = wd.kun_manpower_stamp()
    key = (stamp, days_req)
    hit = _MP_CACHE.get(key)
    if hit is not None:
        return hit
    doc, _st = wd.load_kun_manpower()
    board = wm.build_manpower_board(doc, days_req=days_req)
    for k in [k for k in _MP_CACHE if k[0] != stamp]:
        _MP_CACHE.pop(k, None)              # 檔換版＝舊印記整批作廢（三檔觀測長度各留一份）
    _MP_CACHE[key] = board
    return board


# (public build: route decorator removed - excluded page)
def manpower(request: Request, source: str = DEFAULT_SOURCE, lang: str = "en",
             days: int = 0):
    """流程站人力頁：列＝PLOVER 原表流程站、綑＝跨列的視覺群組帶、欄＝我方真的量到的桶。
       全部數字＝**有操作紀錄的匿名人數下界**（C-MP11；口徑一行常駐＋頁尾全文＝C-PLANT1／SPEC §7）。
       `days` ∈ {7,14,30}＝可調觀測長度（純參數、零新查詢）。"""
    source = _route_source(source)
    import board_runwindow as wrw
    import board_manpower as wm
    mp = _load_manpower_board(days)
    age_d = None
    if mp and mp.get("cap"):
        try:
            import datetime as _dt
            cap = _dt.datetime.fromisoformat(str(mp["cap"]).split(".")[0])
            age_d = max(0, (_dt.datetime.now() - cap).days)
        except Exception:
            age_d = None
    tt = I18N[resolve_lang(lang)]
    # 桶顯示名（C-MP5 位置描述；細桶＝計畫窗外①②，牆鐘窗在 [E] 對照表）
    lbl = {"day": tt["mp_b_day"], "swing": tt["mp_b_swing"], "night": tt["mp_b_night"],
           "outside": tt["mp_b_outside"]}
    for region in ("ZC", "ZAB"):
        for i, (name, _lo, _hi) in enumerate(wrw.outside_gaps(region)):
            lbl[name] = f"{tt['mp_b_outside']} {'①②③'[i]}"
    # 桶 → 牆鐘時段（§4.1 ⑥「必須顯示各段的牆鐘窗」的像素形：細桶的 bar 直接以時段當標籤）
    span = {}
    for _rg, _rows in (mp or {}).get("shift_ref", {}).items():
        for _b, _sp in _rows:
            span.setdefault(_b, _sp)
    d_sel = (mp or {}).get("days_req") or wm.DAYS_DEFAULT
    ctx = {"mp": mp, "age_d": age_d, "BUCKET_LABEL": lbl, "BUCKET_SPAN": span,
           "WEEKDAYS": ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"),
           "days_sel": d_sel, "days_choices": list(wm.DAYS_CHOICES),
           "days_href": (lambda n, _s=source, _l=resolve_lang(lang):
                         f"/manpower?source={_s}&lang={_l}&days={n}"),
           "source": source, "no_source": True,
           "lang_href": (f"/manpower?source={source}&days={d_sel}"
                         f"&lang={'zh' if resolve_lang(lang) == 'en' else 'en'}")}
    ctx.update(i18n_ctx(lang))
    return templates.TemplateResponse(request, tpl(request, "manpower.html"), ctx)


# ---------------------------------------------------------------------------
# /budget —— 設備維護預算與訂單追蹤（SPEC-BUDGET.md；資料層＝board_budget.py）
#   資料源＝**姊妹專案 opswiki-mcp 的 canonical SQLite**（唯讀），經他們的 `reports.py`。
#   ⚠ 本層只做 ctx 組裝與 TTL 快取，**不碰口徑、不算金額、不寫 SQL**（C-BG1/2）。
#   ⚠ **SALTMARSH 隧道零曝**：`/budget` 在 `board_basicauth.TIER_PREFIXES` ⇒ saltmarsh 層一律 404；
#     nav 的標籤由 `_tunnel_ctx` 分層。兩件事分開釘（smoke `budget_round`）。
#   ⚠ 本頁**不進暖機輪**、**不掛 auto-refresh**（C-BG5：對他們的 DB 零週期性負載）。
# ---------------------------------------------------------------------------
_BG_CACHE = {}


def _load_budget_board(period, month, display, statuses_raw):
    """TTL 快取（`board_budget.CACHE_TTL_S`）。**這不是自動刷新**——沒有任何計時器會在
       沒人開這一頁的時候去讀他們的 DB；TTL 只是擋連點與 htmx 換板的重複讀。"""
    # ⚠ DB 路徑進快取鍵：`BOARD_OpsWiki_DB` 換了（搬機、測試）⇒ 舊板當場作廢，不必重啟。
    key = (str(_wbg.opswiki_db_path()), period, month, display, statuses_raw)
    now = time.time()
    hit = _BG_CACHE.get(key)
    if hit is not None and (now - hit[0]) < _wbg.CACHE_TTL_S:
        return hit[1]
    board = _wbg.load_board(period=period, month=month, display=display,
                            statuses_raw=statuses_raw)
    for k, (ts, _v) in list(_BG_CACHE.items()):
        if (now - ts) >= _wbg.CACHE_TTL_S:
            _BG_CACHE.pop(k, None)              # 過期整批清，不無限長大
    _BG_CACHE[key] = (now, board)
    return board


def _bg_ctx(request, lang, period, month, display, st):
    """兩條路由共用的 ctx。控制列的連結**同時**給 shell（可深連結／無 JS 可用）與
       fragment（htmx 只換板）兩個 URL——deep-link 是我方比他們原版多做的一件事。"""
    _lang = resolve_lang(lang)
    board = _load_budget_board(period, month, display, st)
    cur = {"period": board.get("period", period), "month": board.get("month", month),
           "display": board.get("display", display), "st": st, "lang": _lang}

    def ctl(**over):
        p = dict(cur)
        p.update(over)
        qs = urlencode({k: v for k, v in p.items() if v not in (None, "")})
        return {"shell": f"/budget?{qs}", "frag": f"/budget/body?{qs}"}

    def st_link(one):
        sel = (board.get("track") or {}).get("selected") or []
        ladder = (board.get("track") or {}).get("ladder") or []
        return ctl(st=_wbg.toggle_status(sel, one, ladder))

    ctx = {"b": board, "ctl": ctl, "st_link": st_link,
           "usd": _wbg.usd, "abbr": _wbg.month_abbr,
           # 本頁**沒有** source 語意（沒有 demo 形）——但 `_nav.html` 的其他分頁連結要帶
           # `source=`，少了它會渲染成 `?source=`（空值）⇒ 給 nav 一個合法預設值。
           "source": DEFAULT_SOURCE, "no_source": True,
           "frag_qs": urlencode({k: v for k, v in cur.items() if v not in (None, "")}),
           "lang_href": ctl(lang=("zh" if _lang == "en" else "en"))["shell"]}
    ctx.update(i18n_ctx(lang))
    return ctx


