@app.get(DT_BASE, response_class=HTMLResponse)
def downtime(request: Request, source: str = DEFAULT_SOURCE, lang: str = "en", months: str = "",
             type: str = "all"):
    """停機月報外殼（瞬開）；資料板由 `DT_BASE/body` hx-get 進來。`from`／`to` 由 `_dt_from_to` 取。"""
    ctx = _dt_ctx(request, source, lang, months, type)
    return templates.TemplateResponse(request, tpl(request, "downtime.html"), ctx)


@app.get(DT_BASE + "/body", response_class=HTMLResponse)
def downtime_body(request: Request, source: str = DEFAULT_SOURCE, lang: str = "en", months: str = "",
                  type: str = "all"):
    """資料板 fragment：KPI 列＋堆疊長條（inline SVG）＋表格孿生＋面板版位＋頁尾。"""
    t0 = time.perf_counter()
    ctx = _dt_ctx(request, source, lang, months, type)
    resp = templates.TemplateResponse(request, tpl(request, "_downtime_body.html"), ctx)
    print(f"[downtime] body source={ctx['source']} months={len(ctx['sel'])} "
          f"{time.perf_counter() - t0:.3f}s", flush=True)
    return resp


def _dt_detail_texts(mode, info, wnos, lang):
    """五張單的原文（§8「原文一鍵可見」）＋原始 detail（摘要輸入）。
       demo＝fixture 罐頭（零 cmms）；live＝`fetch_pm_wo_detail` 並行（≈0.3s/張）；其餘＝空。
       回 `{wno: {"fields": [(label_key, text)…], "raw": detail|None, "err": reason|None}}`。"""
    out = {}
    if mode == "demo":
        det = ((info.get("demo") or {}).get("details") or {})
        for w in wnos:
            d = det.get(str(w)) or {}
            fields = []
            for k, lk in (("brief_description", "dt_f_brief"), ("diagnosis", "dt_f_diag"),
                          ("action_taken", "dt_f_action")):
                if d.get(k):
                    fields.append((lk, d[k].get(lang) or d[k].get("en")))
            out[str(w)] = {"fields": fields, "raw": None, "err": None}
        return out
    if mode != "live":
        return {str(w): {"fields": [], "raw": None, "err": None} for w in wnos}
    from concurrent.futures import ThreadPoolExecutor
    import json as _json                      # 本檔無 module 級 json；live detail 的 parts／notes 可能是 list／dict（09-23 live 500 實證）

    _DT_ACTOR_KEYS = ("actor", "person", "user", "assignee", "technician", "created_by", "updated_by",
                      "closed_by", "owner", "operator", "reporter", "requested_by", "by")

    def _dt_scrub(v):
        """§24／C-DT12：原文段**不得帶人**——detail 的 notes／parts 是 list[dict]，裡面有
        `source_actor: human:<帳號>` 這類欄（09-23 live 面板實證外洩 `human:grace.yu`）。
        遞迴剝掉鍵名含人員語意的欄；notes 只留 `occurred_at`＋`body`（讀者要的是內容不是誰寫）。"""
        if isinstance(v, dict):
            return {k: _dt_scrub(x) for k, x in v.items()
                    if not any(a in str(k).lower() for a in _DT_ACTOR_KEYS)}
        if isinstance(v, list):
            return [_dt_scrub(x) for x in v]
        return v

    def _dt_flat(k, v):
        """notes（list[dict{occurred_at, body}]）攤成「時間 body」逐行；其餘非字串走 JSON（已剝人員欄）。"""
        v = _dt_scrub(v)
        if k == "notes" and isinstance(v, list) and all(isinstance(x, dict) for x in v):
            lines = []
            for x in v:
                body = str(x.get("body") or "").strip()
                if body:
                    lines.append(("%s %s" % (str(x.get("occurred_at") or "")[:16].replace("T", " "), body)).strip())
            return "\n".join(lines)
        return v if isinstance(v, str) else _json.dumps(v, ensure_ascii=False)

    def _one(w):
        try:
            d, why = w8t.fetch_pm_wo_detail(w)
        except Exception as e:                           # noqa: BLE001
            d, why = None, type(e).__name__
        return str(w), d, why
    with ThreadPoolExecutor(max_workers=5) as ex:
        for w, d, why in ex.map(_one, wnos):
            fields = []
            for k, lk in (("brief_description", "dt_f_brief"), ("diagnosis", "dt_f_diag"),
                          ("action_taken", "dt_f_action"), ("notes", "dt_f_notes"), ("parts", "dt_f_parts")):
                v = (d or {}).get(k)
                if v in (None, "", [], {}):
                    continue
                fields.append((lk, _dt_flat(k, v)))
            out[w] = {"fields": fields, "raw": d, "err": why}   # raw 不剝：輸出清洗黑名單（detail_person_values）要從它讀
    return out


_DT_BUDGET_LOCK = threading.Lock()


def _dt_budget_take():
    """保險絲「查＋記」**原子化**：五張單並行摘要時，分開的 check／commit 會一起通過、超額
       （smoke 實測踩到）。鎖內先查、放行才加一＝「計的是送出去的那一次」。"""
    with _DT_BUDGET_LOCK:
        if not wassist.llm_budget_check("summary")[0]:
            return False
        wassist.llm_budget_commit("summary")
        return True


def _dt_summaries(mode, info, rows, texts, lang):
    """P3 LLM 摘要（SPEC-DOWNTIME §8）→ `{wno: {"state", "text", "reason"}}`。**恆不 raise。**

       · demo：fixture 罐頭摘要、`state='demo'`（標「AI 摘要（示範）」）——**零 LLM 呼叫**（C-DT11）。
       · live：懶算＝點段才算這五張；呼叫路徑＝`_hermes_post(prompt, path="/translate")`（翻譯快車道：
         無工具、無 persona；**不改 gateway**）；保險絲＝`summary` 桶（`BOARD_SUMMARY_DAILY_MAX`）；
         快取＝`wo_summary`（`board_downtime.summary_cache_*`；鍵 (wo_no, lang, prompt_version)＋detail_hash）；
         gateway 未設定／不可達 ⇒ `unavailable`、原文照顯、**不燒桶、不寫快取、不重試**。
       · 其餘：`off`。"""
    out = {}
    if mode == "demo":
        canned = (info.get("demo") or {}).get("summaries") or {}
        for r in rows:
            txt = (canned.get(str(r["wo_no"])) or {}).get(lang)
            out[str(r["wo_no"])] = ({"state": "demo", "text": txt} if txt else {"state": "off", "text": None})
        return out
    if mode != "live":
        return out
    gw_ready = bool(os.environ.get("BOARD_HERMES_URL") and os.environ.get("BOARD_HERMES_SECRET"))

    def _one(r):
        wno = str(r["wo_no"])
        det = (texts.get(wno) or {}).get("raw")
        if det is None:
            return wno, {"state": "unavailable", "text": None, "reason": "detail"}
        conn = None
        try:
            conn = wdt.wl.connect()
            hit = wdt.summary_cache_get(conn, wno, lang, wdt.detail_hash(det))
            if hit:
                return wno, dict(hit, state="cached")
            if not gw_ready:
                return wno, {"state": "unavailable", "text": None, "reason": "gateway"}
            res = wdt.summarize_one(
                det, lang, post=lambda pr: _hermes_post(pr, path="/translate"),
                budget_check=_dt_budget_take, budget_commit=None,
                conn=conn, wo_no=wno)
            return wno, res
        except Exception as e:                                  # noqa: BLE001
            _logerr("downtime summary", e)
            return wno, {"state": "unavailable", "text": None, "reason": "gateway"}
        finally:
            if conn is not None:
                conn.close()
    from concurrent.futures import ThreadPoolExecutor
    with ThreadPoolExecutor(max_workers=5) as ex:
        for wno, res in ex.map(_one, rows):
            out[wno] = res
    return out


@app.get(DT_BASE + "/panel", response_class=HTMLResponse)
def downtime_panel(request: Request, source: str = DEFAULT_SOURCE, lang: str = "en", months: str = "",
                   type: str = "all", month: str = "", area: str = ""):
    """點段 fragment：該區該月 top-5（§7.3）。`month`／`area` 對當前選取白名單；不中＝空片段。"""
    ctx = _dt_ctx(request, source, lang, months, type)
    model = ctx.get("model")
    if not model or month not in ctx["sel"] or area not in wdt.BAR_AREAS:
        return HTMLResponse("")
    L = ctx["t"]
    mm = next(x for x in model["months"] if x["month"] == month)
    rows = [dict(r) for r in model["top"].get((month, area), ())]
    ax = L["dt_axis_24h"] if mm["axis"] == "24h" else L["dt_axis_rw"]
    ctx["panel_head"] = L["dt_panel_head"].format(a=wdt.AREA_LABEL[area], m=month,
                                                   h=_dt_h(mm["areas"].get(area)), axis=ax)
    ctx["panel_rows"] = rows
    ctx["cmms_base"] = _dt_cmms_base(ctx["mode"])
    ctx["show_code"] = any(r.get("fault_code") for r in rows)
    texts = _dt_detail_texts(ctx["mode"], ctx["_info"], [r["wo_no"] for r in rows], ctx["lang"])
    for r in rows:
        tx = texts.get(str(r["wo_no"])) or {}
        r["orig"] = tx.get("fields") or []
    sums = _dt_summaries(ctx["mode"], ctx["_info"], rows, texts, ctx["lang"])
    for r in rows:
        r["summary"] = sums.get(str(r["wo_no"])) or {"state": "off", "text": None}
    # P3 慣犯（§7.3／§14 ⑥）：同區、複選月內進前五 ≥2 次；單月不算（`model["repeat"]` 已依此算好）
    hits = (model.get("repeat") or {}).get(area) or []
    ctx["repeat_line"] = (L["dt_repeat"].format(items="、".join(
        f"{h['display']} {h['eid']}（{h['k']}/{h['n']}）" for h in hits[:3])) if hits else None)
    ctx["panel_area"], ctx["panel_month"] = area, month
    return templates.TemplateResponse(request, tpl(request, "_downtime_panel.html"), ctx)


